[Function(nameof(ProcessBatch))]
public static async Task<int> ProcessBatch(
    [OrchestrationTrigger] TaskOrchestrationContext ctx)
{
    var files = await ctx.CallActivityAsync<string[]>(nameof(ListFiles));
    var tasks = files.Select(f => ctx.CallActivityAsync<int>(nameof(ImportFile), f));
    var counts = await Task.WhenAll(tasks);       // fan-out / fan-in
    return counts.Sum();
}

