[Function(nameof(Approve))]
public static async Task Approve([OrchestrationTrigger] TaskOrchestrationContext ctx)
{
    var requestId = Guid.NewGuid();
    if (DateTime.UtcNow.Hour < 12)
        await ctx.CallActivityAsync(nameof(SendMorningMail), requestId);
    else
        await ctx.CallActivityAsync(nameof(SendEveningMail), requestId);
}
